'use strict';
// All market values and documents are fictional demonstration fixtures.
const coins=[['BTC','비트코인',66770,2.32,1.82,'₿','#d48b30'],['ETH','이더리움',2530,1.87,-.64,'Ξ','#6479bb'],['XRP','리플',.536,3.18,3.27,'×','#3b485b'],['SOL','솔라나',151.8,2.65,4.12,'≋','#7155b8'],['DOGE','도지코인',.142,2.14,-1.23,'Ð','#ae9856'],['ADA','에이다',.354,1.62,.83,'₳','#366eae'],['AVAX','아발란체',27.2,2.81,2.17,'▲','#bf4b53'],['LINK','체인링크',11.28,1.94,-.42,'⬡','#4269c1'],['DOT','폴카닷',4.12,-.36,-2.08,'●','#bd4a87'],['TRX','트론',.158,1.29,.64,'T','#ad434c']].map(([symbol,name,usd,premium,change,glyph,color],index)=>({symbol,name,usd,premium,change,glyph,color,index}));
const $=s=>document.querySelector(s),FX=1380;
const money=n=>Number.isFinite(n)?Math.round(n).toLocaleString('ko-KR'):'—';
const pct=n=>Number.isFinite(n)?(n>=0?'+':'')+n.toFixed(2)+'%':'—';
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
let saved=new Set(read('kimpscope-favorites',[]).filter(x=>coins.some(c=>c.symbol===x))),history=read('kimpscope-chats',{});if(!history||typeof history!=='object'||Array.isArray(history))history={};
let selected=coins[0],filter='all',tab='market',sort=0,paused=false,range='1H',ticks=0;
const pending=new Set();
function persist(){try{localStorage.setItem('kimpscope-favorites',JSON.stringify([...saved]));localStorage.setItem('kimpscope-chats',JSON.stringify(history))}catch{}}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function icon(c){return `<span class="coin-icon" style="background:${c.color}">${c.glyph}</span><span class="coin-text"><b>${c.name}</b><small>${c.symbol}</small></span>`}
function spark(c,large=false){const w=large?280:70,h=large?155:26,seed=c.index+(range==='7D'?8:range==='24H'?4:0),p=Array.from({length:32},(_,i)=>[i*w/31,h*.7-Math.sin(i*.64+seed)*h*.12-Math.sin(i*1.67+seed)*h*.06-i*h*.012]);const path=p.map((v,i)=>(i?'L':'M')+v.join(',')).join(' '),color=c.premium>=0?'#a5ef6b':'#f18091';return `<svg class="${large?'':'spark'}" viewBox="0 0 ${w} ${h}" role="img" aria-label="${c.name} 샘플 추이">${large?`<defs><linearGradient id="fade" x1="0" x2="0" y1="0" y2="1"><stop stop-color="${color}" stop-opacity=".2"/><stop offset="1" stop-color="${color}" stop-opacity="0"/></linearGradient></defs><path d="M0,30 H280 M0,75 H280 M0,120 H280" stroke="#28313b" stroke-dasharray="3 5"/><path d="${path} L280,155 L0,155 Z" fill="url(#fade)"/>`:''}<path d="${path}" fill="none" stroke="${color}" stroke-width="${large?2:1.4}"/></svg>`}
function renderTable(){const query=$('#search').value.trim().toLowerCase();let list=coins.filter(c=>(tab!=='watch'||saved.has(c.symbol))&&(!query||`${c.name} ${c.symbol}`.toLowerCase().includes(query))&&(filter==='all'||(filter==='positive'?c.premium>=2:c.premium<0)));if(sort)list.sort((a,b)=>sort*(a.premium-b.premium));$('#coins').innerHTML=list.map(c=>`<tr class="${selected.symbol===c.symbol?'selected':''}"><td><div class="coin-cell"><button class="star ${saved.has(c.symbol)?'saved':''}" data-star="${c.symbol}" aria-label="${c.name} 관심 코인 ${saved.has(c.symbol)?'해제':'추가'}" aria-pressed="${saved.has(c.symbol)}">${saved.has(c.symbol)?'★':'☆'}</button><button class="coin-select" data-coin="${c.symbol}">${icon(c)}</button></div></td><td>${money(c.usd*FX*(1+c.premium/100))}</td><td>${money(c.usd*FX)}</td><td class="${c.premium>=0?'positive':'negative'}">${pct(c.premium)}</td><td class="${c.change>=0?'positive':'negative'}">${pct(c.change)}</td><td>${spark(c)}</td></tr>`).join('');$('#count').textContent=list.length+'개 자산';$('#empty').hidden=list.length>0;$('#table-title').textContent=tab==='watch'?'관심 코인':'거래소 시세 비교';}
function renderDetail(){const c=selected;$('#selected-name').innerHTML=`<div class="coin-select">${icon(c)}</div>`;$('#detail-price').innerHTML=`₩ ${money(c.usd*FX*(1+c.premium/100))}<small>김치 프리미엄 ${pct(c.premium)}</small>`;$('#up-price').textContent='₩ '+money(c.usd*FX*(1+c.premium/100));$('#bin-price').textContent='$ '+c.usd.toLocaleString('en-US',{maximumFractionDigits:4});$('#chart').innerHTML=spark(c,true);$('#range-start').textContent=range==='1H'?'60분 전':range==='24H'?'24시간 전':'7일 전';}
function docs(c){return [{title:`${c.name} 입출금 네트워크 확인 안내`,type:'네트워크 가이드',body:`[가상 샘플 문서] ${c.name}(${c.symbol}) 전송 전 출금 거래소와 입금 거래소가 동일한 네트워크를 지원하는지 확인하세요. 주소와 필요 시 메모·태그를 함께 확인해야 합니다. 이 문서는 현재 입출금 가능 상태를 제공하지 않습니다.`},{title:`${c.symbol} 지갑 점검 공지 예시`,type:'거래소 공지',body:`[가상 샘플 문서] ${c.symbol} 지갑 점검 시 입출금이 일시 중지될 수 있으며, 거래 가능 여부와 입출금 가능 여부는 별도로 확인해야 합니다. 점검 종료 공지와 현재 거래소 상태를 확인하세요. 실제 진행 중인 점검을 의미하지 않습니다.`},{title:`${c.name} 가격 차이와 전송 비용`,type:'자산 가이드',body:`[가상 샘플 문서] 김치 프리미엄은 국내 가격과 환산된 해외 가격의 차이입니다. ${c.symbol}의 표시 프리미엄에는 거래 수수료, 출금 수수료, 호가 슬리피지, 전송 시간 동안의 가격 변동이 포함되지 않습니다. 가격 차이만으로 수익을 확정할 수 없습니다.`}];}
function showModal(title,body){$('#modal-body').innerHTML=`<h2>${esc(title)}</h2><p>${esc(body).replace(/\n/g,'<br>')}</p>`;$('#modal').showModal()}
function showDoc(symbol,index){const c=coins.find(x=>x.symbol===symbol),d=docs(c)[index];if(d)showModal(d.title,`${d.type} · ${c.symbol} 전용 샘플\n출처: 프로젝트 내 가상 데모 문서 / 문서 ${index+1}\n\n${d.body}\n\n실제 거래소가 발행한 공지가 아닙니다. 실서비스에서는 원문 URL, 게시 시각, 수집 시각 및 개정 이력이 연결됩니다.`)}
function renderNotices(){$('#notices').innerHTML=docs(selected).map((d,i)=>`<button class="notice" data-doc="${i}"><span class="notice-symbol">${['⇄','◷','≡'][i]}</span><span><b>${d.title}</b><small>${d.type} · ${selected.symbol} · 가상 샘플</small></span><span>↗</span></button>`).join('')}
function renderChat(){const symbol=selected.symbol;$('#chat-scope').textContent=`${selected.name} (${symbol}) · 독립 대화`;const messages=Array.isArray(history[symbol])?history[symbol]:[];$('#messages').innerHTML=messages.length?messages.map(m=>`<div class="message ${m.role==='user'?'user':'answer'}">${esc(m.text)}${Array.isArray(m.refs)?m.refs.map(i=>`<button data-ref="${i}" data-symbol="${symbol}">[${i+1}] ${esc(docs(selected)[i]?.type||'문서')}</button>`).join(''):''}</div>`).join(''):`<div class="welcome">${selected.name}의 시세만으로 알 수 없는 것들.<br>관련 공지와 전송 조건을 확인해보세요.<small>답변에서 인용된 문서를 직접 열어 근거를 확인할 수 있습니다.</small></div>`;if(pending.has(symbol))$('#messages').insertAdjacentHTML('beforeend','<div class="message">샘플 문서 확인 중…</div>');$('#chat-form button').disabled=pending.has(symbol);$('#clear').disabled=pending.has(symbol);$('#messages').scrollTop=$('#messages').scrollHeight;}
function selectCoin(symbol){selected=coins.find(c=>c.symbol===symbol);renderTable();renderDetail();renderNotices();renderChat()}
function answer(q,c){if(/얼마|현재|지금|수익|예측|오를|내릴|매수|매도|추천/.test(q))return {text:'현재 가격·입출금 상태나 미래 수익은 이 샘플 문서만으로 확인할 수 없습니다. 실제 거래소 시세·상태 API와 최신 원문 확인이 필요합니다. 투자 판단이나 가격 예측을 제공하지 않습니다.',refs:[]};if(/입출금|출금|입금|네트워크|전송|확인/.test(q))return {text:`${c.name} 전송 전에는 다음 내용을 확인하세요.\n1. 양쪽 거래소의 지원 네트워크와 주소·메모를 대조하세요. [1]\n2. 거래 가능 여부와 별개로 입출금 중지·점검 여부를 확인하세요. [2]\n3. 수수료와 전송 중 가격 변동을 고려하세요. [3]\n\n아래 근거는 가상 샘플이며 현재 상태를 보장하지 않습니다.`,refs:[0,1,2]};if(/공지|요약|점검/.test(q))return {text:`${c.name} 샘플 공지의 핵심은 네트워크 일치 여부를 확인하고 [1], 지갑 점검 시 입출금 상태를 따로 확인하는 것입니다. [2]\n\n실제 점검 일정이나 최신 공지는 연결되지 않았습니다.`,refs:[0,1]};if(/프리미엄|가격 차|비용|수수료/.test(q))return {text:'프리미엄은 (국내 가격 ÷ 해외 원화 환산가 − 1) × 100으로 계산합니다. 거래·출금 수수료, 슬리피지와 전송 중 가격 변동은 포함되지 않으므로 표시된 차이가 그대로 수익이 되지는 않습니다. [3]',refs:[2]};return {text:'현재 선택한 코인의 샘플 문서에서 질문에 답할 근거를 찾지 못했습니다. 입출금 확인 사항, 관련 공지 또는 프리미엄 계산 기준을 질문해보세요.',refs:[]};}
function ask(q){const c=selected;if(!q.trim()||pending.has(c.symbol))return;history[c.symbol]=Array.isArray(history[c.symbol])?history[c.symbol]:[];history[c.symbol].push({role:'user',text:q.trim().slice(0,400)});pending.add(c.symbol);$('#question').value='';persist();renderChat();setTimeout(()=>{history[c.symbol].push({role:'assistant',...answer(q,c)});pending.delete(c.symbol);persist();if(selected.symbol===c.symbol)renderChat()},700)}
$('#coins').addEventListener('click',e=>{const star=e.target.closest('[data-star]'),coin=e.target.closest('[data-coin]');if(star){saved.has(star.dataset.star)?saved.delete(star.dataset.star):saved.add(star.dataset.star);persist();renderTable()}else if(coin)selectCoin(coin.dataset.coin)});
$('#search').addEventListener('input',renderTable);$('#sort').onclick=()=>{sort=sort===-1?1:-1;$('#sort').textContent='김치 프리미엄 '+(sort===-1?'↓':'↑');renderTable()};
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));renderTable()});
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));document.body.classList.toggle('news-view',tab==='news');renderTable()});
$('#ranges').onclick=e=>{const b=e.target.closest('[data-range]');if(!b)return;range=b.dataset.range;document.querySelectorAll('[data-range]').forEach(x=>x.classList.toggle('active',x===b));renderDetail()};
$('#notices').onclick=e=>{const b=e.target.closest('[data-doc]');if(b)showDoc(selected.symbol,Number(b.dataset.doc))};$('#messages').onclick=e=>{const b=e.target.closest('[data-ref]');if(b)showDoc(b.dataset.symbol,Number(b.dataset.ref))};
$('#chat-form').onsubmit=e=>{e.preventDefault();ask($('#question').value)};document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>ask(b.dataset.question));$('#clear').onclick=()=>{history[selected.symbol]=[];persist();renderChat()};
$('#close-modal').onclick=()=>$('#modal').close();$('#modal').onclick=e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}};
const about=()=>showModal('프론트엔드 프로토타입 안내','KimpScope는 국내외 코인 시세 비교와 코인별 문서 탐색 흐름을 검증하는 독립 구현입니다.\n\n가격·환율·차트·공지는 모두 가상 데모 데이터입니다. 실제 거래소 API, 로그인, 주문, 문서 수집, 임베딩, 벡터 검색, LLM은 연결되지 않았습니다.\n\n대화는 브라우저에서 규칙 기반으로 생성되며, 관심 코인과 대화 기록은 현재 브라우저에만 저장됩니다. 실제 서비스에서는 서버의 코인별 검색과 출처 검증으로 교체해야 합니다.');$('#about').onclick=about;
$('#method').onclick=()=>showModal('데이터 및 계산 기준','국내 가격 = 해외 USD 가격 × 데모 환율 1,380 × (1 + 데모 프리미엄 / 100)\n프리미엄 = (국내 가격 / 해외 환산가 − 1) × 100\n\n24시간 등락률과 차트는 고정 샘플입니다. 실시간 시세·환율 또는 과거 이력을 의미하지 않습니다. 평균 프리미엄은 10개 샘플 코인의 단순 평균입니다.\n\n시세는 3초마다 브라우저에서 시뮬레이션합니다. 실제 거래소에 연결하지 않으며 금융 거래에 사용해서는 안 됩니다.');
$('#research-link').onclick=()=>{$('.assistant').scrollIntoView({behavior:'smooth',block:'center'});$('#question').focus({preventScroll:true})};
$('#pause').onclick=()=>{paused=!paused;$('#pause').textContent=paused?'▶ 갱신 재개':'Ⅱ 갱신 일시정지';$('.ticker>span').innerHTML=paused?'<i style="background:#7c8798"></i> 시뮬레이션 일시정지':'<i></i> 시뮬레이션 연결됨'};
function updateMetrics(){$('#avg').innerHTML=pct(coins.reduce((a,c)=>a+c.premium,0)/coins.length).replace('%','<span>%</span>');$('#btc').textContent='₩ '+money(coins[0].usd*FX*(1+coins[0].premium/100));const high=coins.reduce((a,c)=>a.premium>c.premium?a:c);$('#highest').innerHTML=high.symbol+' <span>'+pct(high.premium)+'</span>';$('#updated').textContent='마지막 갱신 '+new Date().toLocaleTimeString('ko-KR',{hour12:false})}
selectCoin('BTC');updateMetrics();const demoTimer=setInterval(()=>{if(paused)return;ticks++;coins.forEach(c=>{c.usd*=1+Math.sin(ticks*.5+c.index)*.00015;c.premium+=Math.sin(ticks*.7+c.index)*.008});renderTable();renderDetail();updateMetrics()},3000);
